ct(evidence.profile.frozenRosterRows).toBe(3);expect(evidence.profile.attendanceRecords).toBe(3);expect(evidence.liveSectionDateRoster.executionMs).toBeGreaterThan(0);expect(evidence.frozenRosterRecords.executionMs).toBeGreaterThan(0);expect(evidence.revisionHistory.indexes).toContain('vs_attendance_revision_number_key');expect(evidence.adminDateSessions.executionMs).toBeGreaterThan(0);expect(evidence.teacherAssignedDateSessions.executionMs).toBeGreaterThan(0);expect(evidence.opaqueReceiptLookup.executionMs).toBeGreaterThan(0);expect(evidence.opaqueReceiptLookup.text).not.toContain(cancelReceipt.key);
