  let reached!:()=>void,release!:()=>void;const atSummary=new Promise<void>(resolve=>{reached=resolve;}),barrier=new Promise<void>(resolve=>{release=resolve;});let paused=false;
  const blockedClient=new Proxy(db,{get(target,property){
   if(property==='$transaction')return (work:(tx:unknown)=>Promise<unknown>,options:unknown)=>target.$transaction(async tx=>{
    const proxied=new Proxy(tx,{get(transaction,key){const value=Reflect.get(transaction,key,transaction);if(key==='$queryRaw')return async(...args:unknown[])=>{const rows=await (value as (...values:unknown[])=>Promise<unknown>).apply(transaction,args);if(!paused){paused=true;reached();await barrier;}return rows;};return typeof value==='function'?value.bind(transaction):value;}});
    return work(proxied);
   },options as never);
   const value=Reflect.get(target,property,target);return typeof value==='function'?value.bind(target):value;
  }}) as typeof db;
